/**
 * Normalize text extracted by OpenAI Vision or similar models.
 * Cleans and standardizes Vision output while preserving metadata (e.g. fileName, docType).
 * Works for OpenAI "Analyze Image" output or other message-based formats.
 */

const newItems = [];

for (const outer of items) {
  const meta = outer.json || {};

  // Some OpenAI Vision responses are nested message arrays or structured responses
  const messageArray = Array.isArray(meta) ? meta
    : meta.content ? [meta]
    : Array.isArray(outer) ? outer
    : [outer];

  for (const msg of messageArray) {
    let text = '';

    // --- Extract text safely from common OpenAI output formats ---
    if (msg?.json?.text) {
      text = msg.json.text;
    } else if (msg?.text) {
      text = msg.text;
    } else if (msg?.content && Array.isArray(msg.content)) {
      const contentText = msg.content.find(c => c.type === 'output_text');
      if (contentText?.text) text = contentText.text;
    } else if (typeof msg === 'string') {
      text = msg;
    }

    if (typeof text !== 'string') text = String(text || '');

    // --- Step 1: Basic cleanup ---
    text = text
      .replace(/\r\n/g, '\n')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{2,}/g, '\n\n')
      .replace(/\f/g, ' ')
      .trim();

    // --- Step 2: Remove repeated or noisy labels ---
    const lines = text.split('\n');
    const seen = new Set();
    const filtered = lines.filter(line => {
      const l = line.trim().toLowerCase();
      if (!l || seen.has(l)) return false;
      seen.add(l);
      if (/^(diagram|figure|screenshot|ui|image|architecture|flow|mockup)/i.test(l)) return false;
      return true;
    });
    text = filtered.join('\n').trim();

    // --- Step 3: Normalize punctuation ---
    text = text
      .replace(/\s+([.,;:!?])/g, '$1')
      .replace(/([.,;:!?])([^\s])/g, '$1 $2')
      .replace(/\s{2,}/g, ' ');

    // --- Step 4: Capitalize sentence starts ---
    text = text.replace(/(^|[.!?]\s+)([a-z])/g, (_, prefix, c) => prefix + c.toUpperCase());

    // --- Step 5: Truncate if Vision returns long structured dumps ---
    if (text.length > 5000) {
      text = text.slice(0, 5000) + '... [truncated for processing]';
    }

    // --- Step 6: Attach metadata for merging later ---
    const normalized = {
      normalizedVisionText: text,
      source: 'Vision',
      cleaningStatus: 'normalized',
      fileName: $('Switch - Find Extractor').first().json.fileName || 'Unknown_File',
      fileType: $('Switch - Find Extractor').first().json.fileType || 'Unknown',
      docType: $('Switch - Find Extractor').first().json.docType || 'Unknown',
      requiresVision: $('Switch - Find Extractor').first().json.requiresVision ?? true,
      contentType: $('Switch - Find Extractor').first().json.contentType || 'image',
    };

    newItems.push({ json: normalized });
  }
}

return newItems;

